export const resolveDefaultNodeEnv = (
  packageRootAbsolutePath: string,
  packageName: string,
): 'production' | 'development' => {
  if (packageName !== 'rivet-design') {
    return 'development';
  }
  const normalized = packageRootAbsolutePath.replace(/\\/g, '/');
  const isPublishedLayout = /(?:^|\/)node_modules\/rivet-design(?:\/|$)/.test(
    normalized,
  );
  return isPublishedLayout ? 'production' : 'development';
};
